// Map failure according to PRD Section 11 table
const err = $json.execution.error;
const message = err.message || 'Unknown automation failure';

let category = 'network';
if (message.includes('429') || message.includes('rate limit')) category = 'rate_limit';
else if (message.includes('schema') || message.includes('validation')) category = 'validation';
else if (message.includes('credential') || message.includes('auth')) category = 'credential';
else if (message.includes('credit')) category = 'credit_exhaustion';
else if (message.includes('AI') || message.includes('Gemini')) category = 'ai_output';

return {
  workflow_name: $json.workflow.name,
  failed_step: $json.execution.lastNodeExecuted || 'unknown_step',
  failure_category: category,
  error_message: message,
  correlation_id: 'err_' + Date.now()
};
